@startuml

class Song {
  + title : string
  + year : int
  + length : time
  + genre : string
}

class Artist {
  + name : string
  + birthDate : date
  + website : string
}

class User {
  + ID : int
  + name : string
  + address : string
}

class BusinessUser {
  + VATNumber : string
}

class RegularUser {}

class Album {
  + title : string
  + trackNumber : int
}

enum SongType {
  single
  hit
}

class Content {
  + type : SongType
}

class Single {}
class Hit {}

Single --|> Content
Hit --|> Content

Song "1" -- "1" Artist
User "1" -- "*" Content
BusinessUser "0..*" -- "1..*" Song
RegularUser "0..*" -- "0..*" Album
Album "1" -- "*" Hit

@enduml

